unsigned s5l8900_static_a64_cached_witness_bytes(const s5l8900_t *m,
                                                 uint32_t pc, bool thumb) {
#if defined(S5LBOX_STATIC_A64_ENGINE)
    const static_a64_state_t *state = static_state(m);
    if (!state) return 0u;
    for (unsigned i = 0u; i < STATIC_A64_CACHE_ENTRIES; i++) {
        const static_a64_entry_t *entry = &state->cache[i];
        if (entry->valid && entry->pc == pc && entry->thumb == thumb)
            return entry->raw_len;
    }
#else
    (void)m;
    (void)pc;
    (void)thumb;
#endif
    return 0u;
}

#if defined(S5LBOX_STATIC_A64_ENGINE)
static unsigned try_persistent(s5l8900_t *m, static_a64_state_t *state,
                               unsigned budget) {
    arm_cpu_t *cpu = &m->cpu;
    static_a64_chain_context_t context = {
        .state = state,
        .machine = m,
        .fetch_block = cpu->r[15] & ~UINT32_C(0x3ff)
    };
    const a64_static_block_t *first =
        select_persistent_block(&context, cpu->r[15], budget);
    unsigned completed = 0u;
    unsigned blocks = 0u;

    if (!first) return 0u;
    if (!a64_static_run_read_hits_chain(cpu, first, m->ram, m->ram_size,
                                        budget, persistent_next, &context,
                                        &completed, &blocks)) {
        /* A pre-execution contract mismatch must not become a sticky cache
         * hit. Runtime read/VFP misses are successful exact-prefix returns. */
        if (context.last_entry)
            invalidate_entry(state, context.last_entry);
        return 0u;
    }
    state->retired += completed;
    if (blocks > 1u) {
        state->chained_blocks += blocks - 1u;
        state->persistent_chained_blocks += blocks - 1u;
    }
    return completed;
}

static unsigned try_graph(s5l8900_t *m, static_a64_state_t *state,
                          unsigned budget) {
    arm_cpu_t *cpu = &m->cpu;
    static_a64_chain_context_t context = {
        .state = state,
        .machine = m,
        .fetch_block = cpu->r[15] & ~UINT32_C(0x3ff)
    };
    const a64_static_block_t *first =
        select_persistent_block(&context, cpu->r[15], budget);
    unsigned completed = 0u;
    unsigned blocks = 0u;

    if (!first) return 0u;
    /* The direct table is intentionally scoped by offset, so a descriptor at
     * the same offset in another 1 KiB fetch block may have replaced this
     * cache entry's node. Ensure the C-validated first head is published, but
     * leave an already-owned valid node untouched on the common hot hit. This
     * lets a returning block recover without recopying 128 bytes per entry. */
    {
        static_a64_entry_t *entry = context.last_entry;
        a64_static_graph_node_t *node =
            &state->graph_nodes[graph_index(entry->pc, entry->thumb)];
        if (node->owner != entry || !node->valid || !node->supported)
            publish_graph_node(state, entry);
    }
    if (!a64_static_run_read_hits_graph(cpu, first, m->ram, m->ram_size,
                                        budget, state->graph_nodes, &completed,
                                        &blocks)) {
        if (context.last_entry)
            invalidate_entry(state, context.last_entry);
        return 0u;
    }
    state->retired += completed;
    if (blocks > 1u) {
        state->chained_blocks += blocks - 1u;
        state->graph_chained_blocks += blocks - 1u;
    }
    return completed;
}
#endif

unsigned s5l8900_static_a64_try(s5l8900_t *m, unsigned max_insns) {
#if defined(S5LBOX_STATIC_A64_ENGINE)
    static_a64_state_t *state = static_state(m);
    arm_cpu_t *cpu;
    unsigned budget;
    unsigned retired = 0u;
    unsigned executed_blocks = 0u;

    if (!state || !state->enabled || !max_insns ||
        !a64_static_host_available() || !m->ram || !m->ram_size ||
        (m->ram_size & (m->ram_size - 1u)) != 0u)
        return 0u;

    cpu = &m->cpu;
    budget = max_insns < STATIC_A64_CHAIN_INSNS
           ? max_insns : STATIC_A64_CHAIN_INSNS;
    if (state->graph_enabled) return try_graph(m, state, budget);
    if (state->persistent) return try_persistent(m, state, budget);

    while (retired < budget) {
        uint32_t pc;
        uint32_t fetch_block;
        unsigned width;
        unsigned offset;
        unsigned candidate_insns;
        unsigned raw_len;
        unsigned remaining = budget - retired;
        unsigned completed = 0u;
        bool thumb;
        bool priv;
        const uint8_t *bytes;
        static_a64_entry_t *entry;
        a64_static_block_t bounded_block;
        const a64_static_block_t *run_block;

        /* Recheck every head. Signed instructions cannot change the MMU,
         * privilege, interrupt masks or instruction state, but keeping these
         * gates local makes that invariant fail closed if the subset grows. */
        if (cpu->arch != ARM_ARCH_V6_ARM1176 ||
            !arm_mode_is_valid(cpu->cpsr) || cpu->abort_pending ||
            (cpu->fiq_line && !(cpu->cpsr & ARM_CPSR_F)) ||
            (cpu->irq_line && !(cpu->cpsr & ARM_CPSR_I)))
            break;

        pc = cpu->r[15];
        thumb = (cpu->cpsr & ARM_CPSR_T) != 0u;
        priv = (cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR;
        width = thumb ? 2u : 4u;
        if ((pc & (width - 1u)) != 0u) break;

        fetch_block = pc & ~UINT32_C(0x3ff);
        /* A cross-block target must return to arm_step(), which alone owns
         * instruction translation, MMU faults and the new fetch witness. */
        if (!cpu->fetch_host || cpu->fetch_blk != fetch_block ||
            cpu->fetch_gen != cpu->tlb_gen || cpu->fetch_priv != priv)
            break;

        offset = pc - fetch_block;
        candidate_insns = (0x400u - offset) / width;
        if (candidate_insns > A64_STATIC_MAX_INSNS)
            candidate_insns = A64_STATIC_MAX_INSNS;
        if (!candidate_insns) break;
        raw_len = candidate_insns * width;
        bytes = cpu->fetch_host + offset;

        entry = &state->cache[cache_index(pc, thumb, cpu->fetch_gen)];
        if (!entry_matches(entry, cpu, bytes, pc, thumb, priv, raw_len))
            decode_entry(state, entry, cpu, bytes, pc, thumb, priv,
                         candidate_insns, raw_len);
        if (!entry->supported) break;
        run_block = &entry->block;
        if (run_block->insn_count > remaining) {
            /* The total chain never crosses its caller/time/device budget.
             * Decode an exact bounded prefix without mutating the cache. */
            if (!decode_longest(bytes, remaining, thumb, pc,
                                &bounded_block))
                break;
            run_block = &bounded_block;
        }

        if (!a64_static_run_read_hits_decoded(cpu, run_block, m->ram,
                                              m->ram_size, &completed)) {
            /* Fail closed, and make a transient contract mismatch re-decode.
             * The decoded runner refuses before changing guest state. */
            invalidate_entry(state, entry);
            break;
        }
        if (!completed) break;
        if (executed_blocks) state->chained_blocks++;
        executed_blocks++;
        retired += completed;
        if (completed != run_block->insn_count) break;
    }

    state->retired += retired;
    return retired;
#else
    (void)m;
    (void)max_insns;
    return 0u;
#endif
}

void s5l8900_static_a64_dispose(s5l8900_t *m) {
    if (!m) return;
#if defined(S5LBOX_STATIC_A64_ENGINE)
    free(m->static_a64_state);
#endif
    m->static_a64_state = NULL;
}
